   "cell_type": "code",
   "execution_count": 14,
   "metadata": {},
   "outputs": [],
   "source": [
    "# Check and remove duplicate columns\n",
    "htmltableDF <- htmltableDF[, !duplicated(colnames(htmltableDF))]"
