    "\n",
    "# Define a function to write to CSV\n",
    "writeCSV <- function(dataframe, filepath, row.names=FALSE) {\n",
    "    write.csv(dataframe, file = filepath, row.names=FALSE)\n",
    "}\n",
    "\n",
    "# Write Dataframe to CSV using a function\n",
