    "# define a function to standardise the columns (change columns to uppercase and replace spaces with underscore) \n",
    "standardise_dataset <- function(dataset) {\n",
    "    names(dataset) <- names(dataset) %>% str_replace_all(\" \", \"_\") %>% toupper(.)  \n",
    "    return(dataset)\n",
    "}"
   ]
