   "source": [
    "# cross reference to ensure reference links were removed\n",
    "sub_bike_sharing_system_df %>% \n",
    "    select(CITY, SYSTEM, COUNTRY) %>% \n",
    "    filter(find_reference_pattern(CITY) | \n",
    "           find_reference_pattern(SYSTEM) | \n",
    "           find_reference_pattern(COUNTRY)\n",
    "          )"
   ]
  },
  {
   "cell_type": "markdown",
   "metadata": {},
   "source": [
    "#### Extract the numeric value using regular expressions"
   ]
  },
  {
   "cell_type": "code",
   "execution_count": 37,
   "metadata": {},
   "outputs": [],
   "source": [
    "# write a function to xtract the first numbers from bicycle column using strinr extract\n",
    "extract_numeric <- function(columns) {\n",
    "  digital_pattern <- '^\\\\d+' # set pattern\n",
    "  extracted <- str_extract(columns, digital_pattern)\n",
    "  extracted <- as.numeric(extracted)\n",
    "  return(extracted)\n",
    "}"
   ]
  },
  {
   "cell_type": "code",
   "execution_count": 38,
   "metadata": {},
   "outputs": [],
   "source": [
    "# Use the mutate() function on the BICYCLES column\n",
    "sub_bike_sharing_system_df <- sub_bike_sharing_system_df %>% mutate(BICYCLES=extract_numeric(BICYCLES))"
   ]
  },
