   "source": [
    "#### Normalise using the min-max scaler"
   ]
  },
  {
   "cell_type": "code",
   "execution_count": 53,
   "metadata": {},
   "outputs": [],
   "source": [
    "# Create a min-max scaler normalisation function\n",
    "minmax_scaler <- function(columns) {\n",
    "  (columns - min(columns)) / (max(columns) - min(columns))\n",
    "} "
   ]
  },
  {
   "cell_type": "code",
   "execution_count": 54,
   "metadata": {},
   "outputs": [],
   "source": [
    "# Use the mutate function to apply the min-max scaler to the variables \n",
    "# (rented bike count, temp, humidity, wind speed, visibility, dew_point temp, solar rad, rainfall and snowfall)\n",
    "seoul_bike_sharing_normalised_df <- seoul_bike_sharing_converted_df %>%\n",
    "  mutate(\n",
    "    RENTED_BIKE_COUNT = minmax_scaler(RENTED_BIKE_COUNT), \n",
    "    TEMPERATURE = minmax_scaler(TEMPERATURE), \n",
    "    HUMIDITY = minmax_scaler(HUMIDITY),\n",
    "    WIND_SPEED = minmax_scaler(WIND_SPEED),\n",
    "    VISIBILITY = minmax_scaler(VISIBILITY),\n",
    "    DEW_POINT_TEMPERATURE = minmax_scaler(DEW_POINT_TEMPERATURE),\n",
    "    SOLAR_RADIATION = minmax_scaler(SOLAR_RADIATION),\n",
    "    RAINFALL = minmax_scaler(RAINFALL),\n",
    "    SNOWFALL = minmax_scaler(SNOWFALL)\n",
    "  )"
