   "cell_type": "markdown",
   "metadata": {},
   "source": [
    "### Standardise the Column and Export Dataframes to CSV"
   ]
  },
  {
   "cell_type": "code",
   "execution_count": 56,
   "metadata": {},
   "outputs": [],
   "source": [
    "# Use a list to define the data frame variable\n",
    "dataframes <- list(sub_bike_sharing_system_df, seoul_bike_sharing_df, seoul_bike_sharing_converted_df, seoul_bike_sharing_normalised_df)\n",
    "\n",
    "# Use a vector to define the CSV file names \n",
    "file_names <- c('bike_sharing_systems.csv', \n",
    "                'seoul_bike_sharing.csv', \n",
    "                'seoul_bike_sharing_converted.csv', \n",
    "                'seoul_bike_sharing_converted_normalized.csv')"
   ]
  },
  {
   "cell_type": "code",
   "execution_count": 57,
   "metadata": {},
   "outputs": [],
   "source": [
    "# Define a function to export the data frames as CSV files\n",
    "export_to_csv <- function(dataframes, csv_file_names) {\n",
    "  # Check if the dataframes and CSV file names are the same\n",
    "  if (length(dataframes) != length(csv_file_names)) {\n",
    "    stop(\"Data frames and file names do not have the same length\")\n",
    "  }\n",
    "  \n",
    "  # Iterate through the data frames and file names to save each data frame to a CSV file\n",
    "  for (i in seq_along(dataframes)) {\n",
    "    write_csv(dataframes[[i]], csv_file_names[[i]])\n",
    "  }\n",
    "}"
   ]
  },
  {
   "cell_type": "code",
   "execution_count": 58,
   "metadata": {},
   "outputs": [],
   "source": [
    "# Define a function to standardise column names in the data frames\n",
    "standardise_column_names <- function(dataframe_list) {\n",
    "    colnames(dataframe_list) <- colnames(dataframe_list) %>%\n",
    "    str_replace_all(' ', '_') %>%\n",
    "    toupper()\n",
    "    return(dataframe_list)\n",
    "}"
   ]
  },
  {
   "cell_type": "code",
   "execution_count": 59,
   "metadata": {},
   "outputs": [],
   "source": [
    "# Apply the function to each data frame in the list\n",
    "standardised_dataframe_list <- lapply(dataframes, standardise_column_names)"
   ]
  },
