   "source": [
    "# Scatter plot of rented bike time series\n",
    "ggplot(seoul_bike_sharing, aes(x = DATE, y = RENTED_BIKE_COUNT)) + \n",
    "    geom_point(alpha=0.3) +\n",
    "    labs(x = 'Dates',\n",
    "        y = 'Rented Bike',\n",
    "        title = 'Scatter plot of Rented Bike vs Date') +\n",
    "    theme_light() +\n",
    "    theme(\n",
    "        text = element_text(size = 20)\n",
    "    )"
   ]
