   "source": [
    "# Calculate the total rainfall and snowfall by date\n",
    "daily_total <- seoul_bike_sharing %>% \n",
    "  group_by(DATE) %>%\n",
    "  summarise(total_rain = sum(RAINFALL, na.rm = TRUE),\n",
