   "metadata": {},
   "outputs": [],
   "source": [
    "# Add L1 and L2 regularisation using glmnet engine \n",
    "lr_glmnet <- linear_reg(penalty = 0.01, mixture = 0) %>% \n",
    "    set_engine('glmnet') %>%\n",
    "    set_mode('regression')"
   ]
  },
  {
   "cell_type": "code",
   "execution_count": 117,
   "metadata": {},
   "outputs": [],
   "source": [
    "lm_glmnet <- lr_glmnet %>% fit(RENTED_BIKE_COUNT ~ poly(VISIBILITY, 6) * poly(DEW_POINT_TEMPERATURE, 6) +  \n",
    "                           poly(TEMPERATURE, 4) * poly(SOLAR_RADIATION, 4) + poly(HUMIDITY, 4) * poly(WIND_SPEED, 2) + poly(RAINFALL, 2) * \n",
    "                           poly(SNOWFALL, 2) + ., data=training_data)"
   ]
