   "source": [
    "# Train using the Random Forest model\n",
    "random_forest <- randomForest(\n",
    "  formula = RENTED_BIKE_COUNT ~ ., \n",
    "  data = training_data_random_forest, \n",
    "  ntree = 500,  \n",
    "  mtry = 10,  \n",
    "  importance = TRUE\n",
    ")"
   ]
  },
